sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float radius;
uniform float edgeTol;
uniform float detail;
uniform float amount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 cs = unp(c);
    float3 acc = cs;
    float ws = 1.0;
    for (int i = 0; i < 16; i++) {
        float a = float(i) * 2.3999632;
        float r = sqrt((float(i) + 0.5) / 16.0);
        float4 s4 = tex(coord + float2(cos(a), sin(a)) * r * radius);
        float3 ss = unp(s4);
        float3 dc = ss - cs;
        float w = exp(-dot(dc, dc) / (edgeTol * edgeTol));
        acc += ss * w;
        ws += w;
    }
    float3 o = acc / ws;
    o = o + (cs - o) * detail;
    o = mix(cs, o, amount);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
